35	describe('English Source Integrity (Task 3)', () => {
36	  describe('File existence and basic structure', () => {
37	    for (const pageName of ENGLISH_PAGES) {
38	      it(`${pageName} exists and has valid basic HTML shell`, () => {
39	        const filePath = path.join(ROOT_DIR, pageName);
40	        assert.ok(fs.existsSync(filePath), `File ${pageName} should exist in root directory`);
41	
42	        const content = fs.readFileSync(filePath, 'utf-8');
43	        assert.ok(content.includes('<!DOCTYPE html>'), `${pageName} must have DOCTYPE`);
44	        assert.ok(content.includes('<html lang="en">'), `${pageName} must have <html lang="en">`);
45	        assert.ok(content.includes('</html>'), `${pageName} must have closing </html>`);
46	        assert.ok(content.includes('<head>'), `${pageName} must have <head>`);
47	        assert.ok(content.includes('</head>'), `${pageName} must have </head>`);
48	        assert.ok(content.includes('<body>'), `${pageName} must have <body>`);
49	        assert.ok(content.includes('</body>'), `${pageName} must have </body>`);
50	        assert.ok(!content.includes('</html>tml>'), `${pageName} must not contain malformed trailing tags`);
51	      });
52	    }
53	  });
