55	  describe('Language toggle markup', () => {
56	    for (const pageName of ENGLISH_PAGES) {
57	      it(`${pageName} contains valid language toggle in .sidebar-foot`, () => {
58	        const filePath = path.join(ROOT_DIR, pageName);
59	        const content = fs.readFileSync(filePath, 'utf-8');
60	
61	        // Check .sidebar-foot exists
62	        assert.ok(content.includes('sidebar-foot'), `${pageName} must have .sidebar-foot`);
63	
64	        // Check .lang-toggle exists with correct attributes
65	        assert.ok(
66	          content.includes('<div class="lang-toggle" role="group" aria-label="Language">') ||
67	          content.includes('class="lang-toggle"'),
68	          `${pageName} must contain .lang-toggle`
69	        );
70	
71	        // Check EN link
72	        const enPattern = new RegExp(`<a class="[^"]*lang-opt[^"]*is-active[^"]*" hreflang="en" href="${pageName}">EN<\\/a>`);
73	        assert.match(content, enPattern, `${pageName} must have active EN link pointing to ${pageName}`);
74	
75	        // Check FR link
76	        const frPattern = new RegExp(`<a class="[^"]*lang-opt[^"]*" hreflang="fr" href="fr/${pageName}">FR<\\/a>`);
77	        assert.match(content, frPattern, `${pageName} must have FR link pointing to fr/${pageName}`);
