101	      it(`${pageName} contains /* i18n:STR:start */ block and fmt() helper`, () => {
102	        const filePath = path.join(ROOT_DIR, pageName);
103	        const content = fs.readFileSync(filePath, 'utf-8');
104	
105	        assert.ok(
106	          content.includes('/* i18n:STR:start */'),
107	          `${pageName} must contain /* i18n:STR:start */ block`
108	        );
109	        assert.ok(
110	          content.includes('/* i18n:STR:end */'),
111	          `${pageName} must contain /* i18n:STR:end */ block`
112	        );
113	        assert.ok(
114	          content.includes('const STR = {'),
115	          `${pageName} must declare const STR = { ... }`
116	        );
117	        assert.ok(
118	          content.includes('const fmt ='),
119	          `${pageName} must declare const fmt helper`
120	        );
121	      });
122	    }
123	
124	    for (const pageName of ENGLISH_PAGES) {
125	      it(`${pageName} all inline scripts parse without syntax errors`, () => {
126	        const filePath = path.join(ROOT_DIR, pageName);
127	        const content = fs.readFileSync(filePath, 'utf-8');
128	
129	        const scriptRegex = /<script\b([^>]*)>([\s\S]*?)<\/script>/gi;
130	        let match;
131	        let scriptCount = 0;
132	
133	        while ((match = scriptRegex.exec(content)) !== null) {
134	          const attrs = match[1];
135	          const code = match[2];
136	
137	          // Skip external script tags or module imports with URLs that node VM can't resolve directly
138	          if (attrs.includes('src=') || attrs.includes('type="module"')) {
139	            continue;
140	          }
141	
142	          if (code.trim().length > 0) {
143	            scriptCount++;
144	            assert.doesNotThrow(() => {
145	              new vm.Script(code, { filename: `${pageName}-inline-script-${scriptCount}.js` });
146	            }, `Inline script in ${pageName} must parse without syntax errors`);
147	          }
148	        }
149	      });
150	    }
151	  });
