156	      const content = fs.readFileSync(filePath, 'utf-8');
157	
158	      const matches = content.match(/data-hf-id="[^"]+"/g);
159	      assert.ok(matches && matches.length >= 300, `index.html should retain its data-hf-id attributes (found ${matches ? matches.length : 0})`);
160	    });
161	  });
162	});
