const fs = require('node:fs');
const path = require('node:path');

const ROOT = '/Users/akamaotto/code/icubefarm/sponsor-workspace-prototype';
const EN = path.join(ROOT, 'pan-african-org', 'en');
const DNT_PATH = path.join(ROOT, 'pan-african-org', 'i18n', 'do-not-translate.json');

const DNT = new Set(JSON.parse(fs.readFileSync(DNT_PATH, 'utf8')));

const ALLOWLIST = new Map([
  ['suspend', 'internal type key for openModeration(); compared, never rendered'],
  ['reject', 'internal type key for openModeration(); compared, never rendered'],
]);

function scanLiterals(text) {
  const out = [];
  let i = 0;
  const n = text.length;
  while (i < n) {
    if (text[i] === "'") {
      const startIdx = i;
      i++;
      let value = '';
      while (i < n) {
        const ch = text[i];
        if (ch === '\\') { value += ch + (text[i + 1] || ''); i += 2; continue; }
        if (ch === "'") { i++; break; }
        if (ch === '$' && text[i + 1] === '{') {
          value += '${';
          i += 2;
          let depth = 1;
          while (i < n && depth > 0) {
            const c = text[i];
            if (c === "'" || c === '"' || c === '`') {
              const q = c;
              value += c; i++;
              while (i < n && text[i] !== q) {
                if (text[i] === '\\') { value += text[i] + (text[i + 1] || ''); i += 2; continue; }
                value += text[i]; i++;
              }
              if (i < n) { value += text[i]; i++; }
              continue;
            }
            if (c === '{') depth++;
            else if (c === '}') depth--;
            value += c; i++;
          }
          continue;
        }
        value += ch; i++;
      }
      out.push({ value, index: startIdx });
    } else {
      i++;
    }
  }
  return out;
}

function stripInterpolations(value) {
  let out = '';
  let i = 0;
  const n = value.length;
  while (i < n) {
    if (value[i] === '$' && value[i + 1] === '{') {
      i += 2;
      let depth = 1;
      while (i < n && depth > 0) {
        const c = value[i];
        if (c === "'" || c === '"' || c === '`') {
          const q = c; i++;
          while (i < n && value[i] !== q) { if (value[i] === '\\') i++; i++; }
          if (i < n) i++;
          continue;
        }
        if (c === '{') depth++;
        else if (c === '}') depth--;
        i++;
      }
      continue;
    }
    out += value[i]; i++;
  }
  return out;
}

const HAS_ALPHA_RE = /[A-Za-z]/;
const HEX_RE = /^#[0-9a-fA-F]{3,8}$/;
const CSS_CLASS_RE = /^\.[a-zA-Z][\w-]*$/;
const KEBAB_ID_RE = /^[a-z][a-z0-9]*(?:-[a-z0-9]+)+$/;

function isPureSTRTemplate(rawValue) {
  const stripped = stripInterpolations(rawValue);
  if (stripped.trim() !== '') return false;
  return /\bSTR\.[A-Za-z_][A-Za-z0-9_]*\b/.test(rawValue);
}

function classify(rawValue) {
  if (isPureSTRTemplate(rawValue)) {
    return { bucket: 4, reason: 'routed through STR (template placeholder)' };
  }
  const stripped = stripInterpolations(rawValue).trim();
  if (!HAS_ALPHA_RE.test(stripped)) {
    return { bucket: 1, reason: 'no static alphabetic content' };
  }
  if (HEX_RE.test(stripped)) return { bucket: 1, reason: 'hex colour' };
  if (CSS_CLASS_RE.test(stripped)) return { bucket: 1, reason: 'CSS class name' };
  if (KEBAB_ID_RE.test(stripped)) return { bucket: 1, reason: 'element id / internal token' };
  if (ALLOWLIST.has(stripped)) return { bucket: 2, reason: ALLOWLIST.get(stripped) };
  if (DNT.has(stripped)) return { bucket: 3, reason: 'protected proper noun' };
  return null;
}

function lineOf(text, idx) {
  return text.slice(0, idx).split('\n').length;
}

function extractOnAttrLiterals(html) {
  const results = [];
  const re = /\bon[a-z]+="([^"]*)"/g;
  let m;
  while ((m = re.exec(html))) {
    const attrValue = m[1];
    const attrValueStart = m.index + m[0].indexOf(attrValue);
    for (const lit of scanLiterals(attrValue)) {
      results.push({ value: lit.value, index: attrValueStart + lit.index, source: 'onclick-attr' });
    }
  }
  return results;
}

function extractScriptAlertLiterals(html) {
  const results = [];
  const scriptRe = /<script([^>]*)>([\s\S]*?)<\/script>/gi;
  let sm;
  while ((sm = scriptRe.exec(html))) {
    const attrs = sm[1] || '';
    if (/\bsrc\s*=/.test(attrs)) continue;
    const body = sm[2];
    const openTagLen = sm[0].length - body.length - '</script>'.length;
    const bodyStart = sm.index + openTagLen;

    const callRe = /\b(alert|confirm)\s*\(/g;
    let cm;
    while ((cm = callRe.exec(body))) {
      const argsStart = callRe.lastIndex;
      let depth = 1;
      let i = argsStart;
      while (i < body.length && depth > 0) {
        const c = body[i];
        if (c === '(') depth++;
        else if (c === ')') depth--;
        else if (c === "'" || c === '"' || c === '`') {
          const q = c; i++;
          while (i < body.length && body[i] !== q) { if (body[i] === '\\') i++; i++; }
        }
        i++;
      }
      const argsEnd = i - 1;
      const argsText = body.slice(argsStart, argsEnd);
      for (const lit of scanLiterals(argsText)) {
        results.push({ value: lit.value, index: bodyStart + argsStart + lit.index, source: `${cm[1]}()-in-script` });
      }
      callRe.lastIndex = argsEnd;
    }
  }
  return results;
}

const pages = fs.readdirSync(EN).filter((f) => f.endsWith('.html'));
const stats = { 1: 0, 2: 0, 3: 0, 4: 0 };
const failures = [];

for (const page of pages) {
  const filePath = path.join(EN, page);
  const html = fs.readFileSync(filePath, 'utf8');
  const seen = new Set();
