8	 * on*="..." event-handler attribute, or an alert()/confirm() call inside a
9	 * <script> block. Seven such leaks were found by hand across five pages in
10	 * rounds 1-2 of this task (see task-9-report.md) and fixed by routing them
11	 * through the page's STR object. Nothing automated would have caught a
12	 * regression of that class — this test is that automation.
13	 *
14	 * For every pan-african-org/en/*.html page, this test extracts every JS
15	 * string literal that appears:
16	 *   (a) inside an on*="..." handler attribute, or
17	 *   (b) inside an alert(...)/confirm(...) call within a <script> block,
18	 * and requires each one to fall into exactly one of four buckets:
19	 *   1. Not user-facing   - no static alphabetic content, a hex colour,
20	 *                           a CSS class name (".foo"), or a kebab-case
21	 *                           internal id/token ("invite-modal", "is-open").
22	 *   2. Documented key     - present in ALLOWLIST below, with a comment
23	 *                           explaining why it never reaches the DOM.
24	 *   3. Protected noun     - present in do-not-translate.json.
25	 *   4. Routed through STR - the literal is a template placeholder like
26	 *                           "${STR.foo}" or "${fmt(STR.foo, {...})}".
27	 * A literal matching none of the above fails the test.
28	 */
29	
30	const test = require('node:test');
31	const assert = require('node:assert/strict');
32	const fs = require('node:fs');
33	const path = require('node:path');
34	
35	const ROOT = path.join(__dirname, '..');
36	const EN_DIR = path.join(ROOT, 'pan-african-org', 'en');
37	const DNT_PATH = path.join(ROOT, 'pan-african-org', 'i18n', 'do-not-translate.json');
38	
39	const DO_NOT_TRANSLATE = new Set(JSON.parse(fs.readFileSync(DNT_PATH, 'utf8')));
40	
41	// Bucket 2: documented internal keys. Each entry must carry a one-line
42	// comment proving it is never assigned to .textContent/.innerHTML - only
43	// ever compared against. Keep this list short; if it starts absorbing
44	// genuinely user-facing strings, the gate stops being a gate.
45	const ALLOWLIST = new Map([
46	  // openModeration(type, entityName) in entities.html branches on `type`
47	  // (`type === 'suspend' ? STR.suspendTitle : STR.returnTitle`) to select
48	  // an already-translated string; `type` itself is never written to the
49	  // DOM. Verified across every call site in entities.html.
50	  ['suspend', "openModeration() type key - compared against, never rendered (entities.html)"],
51	  ['reject', "openModeration() type key - compared against, never rendered (entities.html)"],
52	]);
53	
54	// ---------------------------------------------------------------------------
55	// Extraction helpers
56	// ---------------------------------------------------------------------------
57	
58	/**
59	 * Scan `text` for top-level single-quoted string literals. Handles escaped
60	 * quotes (\') and `${...}` template interpolations embedded inside a
61	 * literal - including interpolations that themselves contain nested quoted
62	 * strings (e.g. `'${row.querySelector('strong').textContent}'`, which is
63	 * real markup in entities.html) - without letting the nested quote
64	 * prematurely close the outer literal.
65	 *
66	 * Returns [{ value, index }] where `index` is the position of the opening
67	 * quote and `value` is the literal's raw contents (quotes not included,
68	 * `${...}` blocks left intact for stripInterpolations to handle later).
69	 */
70	function scanLiterals(text) {
71	  const out = [];
72	  let i = 0;
73	  const n = text.length;
74	  while (i < n) {
75	    if (text[i] === "'") {
76	      const startIdx = i;
77	      i++;
78	      let value = '';
79	      while (i < n) {
80	        const ch = text[i];
81	        if (ch === '\\') {
82	          value += ch + (text[i + 1] || '');
83	          i += 2;
84	          continue;
85	        }
86	        if (ch === "'") {
87	          i++;
88	          break;
89	        }
90	        if (ch === '$' && text[i + 1] === '{') {
91	          value += '${';
92	          i += 2;
93	          let depth = 1;
94	          while (i < n && depth > 0) {
95	            const c = text[i];
96	            if (c === "'" || c === '"' || c === '`') {
97	              // Nested quoted string inside the interpolation - consume it
98	              // verbatim so its quotes don't get mistaken for the outer
99	              // literal's closing quote.
100	              const q = c;
101	              value += c;
102	              i++;
103	              while (i < n && text[i] !== q) {
104	                if (text[i] === '\\') {
105	                  value += text[i] + (text[i + 1] || '');
106	                  i += 2;
107	                  continue;
108	                }
109	                value += text[i];
110	                i++;
111	              }
112	              if (i < n) {
113	                value += text[i];
114	                i++;
115	              }
116	              continue;
117	            }
118	            if (c === '{') depth++;
119	            else if (c === '}') depth--;
120	            value += c;
121	            i++;
122	          }
123	          continue;
124	        }
125	        value += ch;
126	        i++;
127	      }
128	      out.push({ value, index: startIdx });
129	    } else {
130	      i++;
131	    }
132	  }
133	  return out;
134	}
135	
136	/** Remove every balanced top-level `${...}` block from a literal's value,
137	 * returning whatever static text (if any) surrounds them. */
138	function stripInterpolations(value) {
139	  let out = '';
140	  let i = 0;
141	  const n = value.length;
142	  while (i < n) {
143	    if (value[i] === '$' && value[i + 1] === '{') {
144	      i += 2;
145	      let depth = 1;
146	      while (i < n && depth > 0) {
147	        const c = value[i];
148	        if (c === "'" || c === '"' || c === '`') {
149	          const q = c;
150	          i++;
151	          while (i < n && value[i] !== q) {
152	            if (value[i] === '\\') i++;
153	            i++;
154	          }
155	          if (i < n) i++;
156	          continue;
157	        }
158	        if (c === '{') depth++;
159	        else if (c === '}') depth--;
160	        i++;
161	      }
162	      continue;
163	    }
164	    out += value[i];
165	    i++;
166	  }
167	  return out;
168	}
169	
170	function extractOnAttrLiterals(html) {
171	  const results = [];
172	  const re = /\bon[a-z]+="([^"]*)"/g;
173	  let m;
174	  while ((m = re.exec(html))) {
175	    const attrValue = m[1];
176	    const attrValueStart = m.index + m[0].indexOf(attrValue);
177	    for (const lit of scanLiterals(attrValue)) {
178	      results.push({ value: lit.value, index: attrValueStart + lit.index, source: 'on*-attribute' });
179	    }
180	  }
181	  return results;
182	}
183	
184	function extractScriptAlertLiterals(html) {
185	  const results = [];
186	  const scriptRe = /<script([^>]*)>([\s\S]*?)<\/script>/gi;
187	  let sm;
188	  while ((sm = scriptRe.exec(html))) {
189	    const attrs = sm[1] || '';
190	    if (/\bsrc\s*=/.test(attrs)) continue; // external script, e.g. gate.js
191	    const body = sm[2];
192	    const openTagLen = sm[0].length - body.length - '</script>'.length;
193	    const bodyStart = sm.index + openTagLen;
194	
195	    const callRe = /\b(alert|confirm)\s*\(/g;
196	    let cm;
197	    while ((cm = callRe.exec(body))) {
198	      const argsStart = callRe.lastIndex;
199	      let depth = 1;
200	      let i = argsStart;
201	      while (i < body.length && depth > 0) {
202	        const c = body[i];
203	        if (c === '(') depth++;
204	        else if (c === ')') depth--;
205	        else if (c === "'" || c === '"' || c === '`') {
206	          const q = c;
207	          i++;
208	          while (i < body.length && body[i] !== q) {
209	            if (body[i] === '\\') i++;
210	            i++;
211	          }
212	        }
213	        i++;
214	      }
215	      const argsEnd = i - 1;
216	      const argsText = body.slice(argsStart, argsEnd);
217	      for (const lit of scanLiterals(argsText)) {
218	        results.push({
219	          value: lit.value,
220	          index: bodyStart + argsStart + lit.index,
221	          source: `${cm[1]}()-in-script`,
222	        });
223	      }
224	      callRe.lastIndex = argsEnd;
225	    }
226	  }
227	  return results;
228	}
229	
230	// ---------------------------------------------------------------------------
231	// Classification
232	// ---------------------------------------------------------------------------
233	
234	const HAS_ALPHA_RE = /[A-Za-z]/;
235	const HEX_RE = /^#[0-9a-fA-F]{3,8}$/;
236	const CSS_CLASS_RE = /^\.[a-zA-Z][\w-]*$/;
237	const KEBAB_ID_RE = /^[a-z][a-z0-9]*(?:-[a-z0-9]+)+$/;
238	const STR_REF_RE = /\bSTR\.[A-Za-z_][A-Za-z0-9_]*\b/;
239	
240	function isPureSTRTemplate(rawValue) {
241	  const stripped = stripInterpolations(rawValue);
242	  if (stripped.trim() !== '') return false; // has literal text outside the interpolation
243	  return STR_REF_RE.test(rawValue);
244	}
245	
246	/** Returns { bucket, reason } for a literal that passes, or null to fail it. */
247	function classify(rawValue) {
248	  if (isPureSTRTemplate(rawValue)) {
249	    return { bucket: 4, reason: 'routed through STR (template placeholder)' };
250	  }
251	
252	  const stripped = stripInterpolations(rawValue).trim();
253	
254	  if (!HAS_ALPHA_RE.test(stripped)) {
255	    return { bucket: 1, reason: 'no static alphabetic content' };
256	  }
257	  if (HEX_RE.test(stripped)) {
258	    return { bucket: 1, reason: 'hex colour' };
259	  }
260	  if (CSS_CLASS_RE.test(stripped)) {
261	    return { bucket: 1, reason: 'CSS class name' };
262	  }
263	  if (KEBAB_ID_RE.test(stripped)) {
264	    return { bucket: 1, reason: 'element id / internal token' };
265	  }
266	  if (ALLOWLIST.has(stripped)) {
267	    return { bucket: 2, reason: ALLOWLIST.get(stripped) };
268	  }
269	  if (DO_NOT_TRANSLATE.has(stripped)) {
270	    return { bucket: 3, reason: 'protected proper noun (do-not-translate.json)' };
271	  }
272	  return null;
273	}
274	
275	function lineOf(text, idx) {
276	  return text.slice(0, idx).split('\n').length;
277	}
278	
279	function collectFailuresAndStats() {
280	  const pages = fs.readdirSync(EN_DIR).filter((f) => f.endsWith('.html'));
281	  const stats = { 1: 0, 2: 0, 3: 0, 4: 0 };
282	  const failures = [];
283	
284	  for (const page of pages) {
285	    const filePath = path.join(EN_DIR, page);
286	    const html = fs.readFileSync(filePath, 'utf8');
287	    const literals = [...extractOnAttrLiterals(html), ...extractScriptAlertLiterals(html)];
288	
289	    // The same literal can textually appear in both passes (an on*="..."
290	    // attribute embedded inside a <script> template literal is picked up
291	    // by both extractors) - dedupe by absolute character offset so it's
292	    // only judged, and reported, once.
293	    const seen = new Set();
294	    for (const lit of literals) {
295	      if (seen.has(lit.index)) continue;
296	      seen.add(lit.index);
297	
298	      const result = classify(lit.value);
299	      const line = lineOf(html, lit.index);
300	      if (!result) {
301	        failures.push(
302	          `${page}:${line} [${lit.source}] ${JSON.stringify(lit.value)} - ` +
303	          'not classified. Route it through STR (STR.<key> / fmt(STR.<key>, {...})), ' +
304	          'add the exact proper noun to pan-african-org/i18n/do-not-translate.json, ' +
305	          'add a justified entry to ALLOWLIST in tests/js-string-literal-gate.test.js, ' +
306	          'or confirm it is genuinely non-user-facing (CSS class/id/hex/numeric).'
307	        );
308	      } else {
309	        stats[result.bucket]++;
310	      }
311	    }
312	  }
313	
314	  return { failures, stats };
315	}
316	
317	// ---------------------------------------------------------------------------
318	// Tests
319	// ---------------------------------------------------------------------------
320	
321	test('no unclassified English JS string literals in on*="..." attributes or alert()/confirm() calls', () => {
322	  const { failures } = collectFailuresAndStats();
323	  assert.deepStrictEqual(
324	    failures,
325	    [],
326	    `Unclassified string literal(s) found:\n  ${failures.join('\n  ')}`
327	  );
328	});
329	
330	test('literal classification stats (informational)', () => {
331	  const { stats } = collectFailuresAndStats();
332	  const total = stats[1] + stats[2] + stats[3] + stats[4];
333	  console.log(
334	    `[js-string-literal-gate] bucket1(not-user-facing)=${stats[1]} ` +
335	    `bucket2(allowlisted-key)=${stats[2]} bucket3(proper-noun)=${stats[3]} ` +
336	    `bucket4(STR-routed)=${stats[4]} total=${total}`
337	  );
338	  assert.ok(total > 0, 'expected at least one classified literal across the org English pages');
339	});
